    fn describe_path_profile(&self, profile: &str) -> &'static str {
        let present = self.path_profiles.iter().any(|(_, value)| value == profile);
        if !present {
            return "missing-profile";
        }
        if profile.starts_with("source-") {
            return "compiled-source";
        }
        if profile.starts_with("script-") {
            return "interpreted-source";
        }
        if profile.starts_with("config-") {
