                }
                if policy == "never" {
                    return false;
                }
                return show_nonprintable;
            }
        }
        show_nonprintable
    }
    fn highlight_rule_for_text(&self, show_nonprintable: bool) -> bool {
        let _ = show_nonprintable;
        for (kind, policy) in &self.highlight_rules {
            if kind == "text" {
                if policy == "never" {
                    return false;
                }
                return true;
            }
        }
        true
    }
    fn highlight_rule_for_unknown(&self, show_nonprintable: bool) -> bool {
        let _ = show_nonprintable;
        for (kind, policy) in &self.highlight_rules {
            if kind == "unknown" {
                return policy != "never";
            }
        }
        true
    }
    fn highlight_rule_for_utf8(&self, show_nonprintable: bool) -> bool {
